void extend(const vector<int>& candidates, size_t start, int remaining, vector<int>& chosen, vector<vector<int>>& out) {
    if (remaining == 0) {
        out.push_back(chosen);
        return;
    }
    for (size_t i = start; i < candidates.size() && candidates[i] <= remaining; ++i) {
        chosen.push_back(candidates[i]);
        extend(candidates, i, remaining - candidates[i], chosen, out);
        chosen.pop_back();
    }
}

vector<vector<int>> combination_sum(vector<int> candidates, int target) {
    sort(candidates.begin(), candidates.end());
    vector<vector<int>> out;
    vector<int> chosen;
    extend(candidates, 0, target, chosen, out);
    return out;
}

